import base64, hashlib, io, json, os, platform, runpy, sys, time, zipfile
from pathlib import Path
import numpy, scipy

started = time.time()
payload = base64.b64decode(
    ""
)
if (
    hashlib.sha256(payload).hexdigest()
    != "f561bc7c3f34654f96deb33ee313a318b6eae7b0cf4e1b19308bc8be3cd0553f"
):
    raise ValueError("frozen payload integrity mismatch")
root = Path("/content/pes_zvf_lineage_20261011")
root.mkdir(parents=True, exist_ok=True)
with zipfile.ZipFile(io.BytesIO(payload)) as z:
    if not all(not Path(n).is_absolute() and ".." not in Path(n).parts for n in z.namelist()):
        raise ValueError("unsafe payload archive path")
    if z.testzip() is not None:
        raise ValueError("payload archive CRC mismatch")
    z.extractall(root)
sys.argv = [
    str(root / "analyze.py"),
    "--input-dir",
    str(root / "inputs"),
    "--output",
    str(root / "result.json"),
]
runpy.run_path(str(root / "analyze.py"), run_name="__main__")
result = json.loads((root / "result.json").read_text())
receipt = {
    "result": result,
    "runtime": {
        "python": platform.python_version(),
        "platform": platform.platform(),
        "numpy": numpy.__version__,
        "scipy": scipy.__version__,
        "cpu_count": os.cpu_count(),
    },
    "payload_sha256": "f561bc7c3f34654f96deb33ee313a318b6eae7b0cf4e1b19308bc8be3cd0553f",
    "remote_elapsed_seconds": time.time() - started,
    "result_file_sha256": hashlib.sha256((root / "result.json").read_bytes()).hexdigest(),
}
print("COLAB_RESULT_JSON=" + json.dumps(receipt, separators=(",", ":"), allow_nan=False))
